import axios from "axios"
import React, { useState } from 'react'
import { useNavigate, useLocation, Link } from 'react-router-dom'

const Update = () => {
    const [member, setMember] = useState({
        name:"",
        membership:"",
        age:""
    })

const navigate = useNavigate()
const location = useLocation()

const memberId = location.pathname.split("/members")[3] // gets the memberId from members/update/:id <- as "id"

print(memberId)

const handleChange = (event) => {
    setMember((prev) => ({ ...prev, [event.target.name]: event.target.value }))
}

const handleClick = async (event) => {
    event.preventDefault() // to prevent default page refresh

    try {
        await axios.put(`http://localhost:8800/members/${memberId}`, member)
        navigate("/members")
    } catch (err) {
        console.log(err)
    }
}

    console.log(member)

    return (
        <div className="form">
            <h1>Update Member</h1>
            <input 
            type="text" 
            onChange={handleChange} 
            placeholder="name" 
            name="name" 
            />
            <input 
            type="text" 
            onChange={handleChange} 
            placeholder="membership" 
            name="membership" 
            />
            <input 
            type="text" 
            onChange={handleChange} 
            placeholder="age" 
            name="age" 
            />
            <button className="formButton" onClick={handleClick}>Update</button>

            <button className="">
                <Link to="/members">Members</Link>
            </button>
        </div>
    )
}

export default Update
